insert into public.resource_hubs(organisation_id,slug,title,description,official_website,status,last_verified_at) select id,'ogc-standards','OGC Standards','Official open geospatial standards, specifications and developer resources.','https://www.ogc.org/','published',timestamptz '2026-09-15T00:00:00+08:00' from public.organisations where slug='ogc' on conflict(slug) do update set title=excluded.title,description=excluded.description,official_website=excluded.official_website,status='published',last_verified_at=excluded.last_verified_at;
insert into public.resource_hub_areas(hub_id,area_id) select h.id,e.id from public.resource_hubs h,public.expertise_areas e where h.slug='ogc-standards' and e.key='geospatial-intelligence' on conflict do nothing;
